  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
  function gravityStep() {
    if (status !== "running" || !current) return;
    if (fits(current, current.row + 1, current.col)) {
      current.row += 1;
      current.lockTicks = 0;
    } else {
      current.lockTicks += 1;
      if (current.lockTicks >= LOCK_TICKS) lockPiece();
    }
  }

  // [REQ-002] Restart the lock delay, at most 3 times per piece.
  // [REQ-005] Sideways moves and soft drops on a resting piece share this budget.
  function resetLock() {
    if (current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets += 1;
      current.lockTicks = 0;
    }
  }

  // [REQ-002] Sideways move. While resting, a move restarts the lock delay.
  function shift(dx) {
    if (!fits(current, current.row, current.col + dx)) return;
    var resting = !fits(current, current.row + 1, current.col);
    current.col += dx;
    if (resting) resetLock();
  }

  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
  function rotateCW() {
    var n = BOX[current.type];
    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
    for (var i = 0; i < KICKS.length; i++) {
      if (fits(rotated, current.row, current.col + KICKS[i])) {
        current.cells = rotated.cells;
        current.col += KICKS[i];
        return;
      }
    }
  }

  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW. [REQ-007] hold.
  // [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
  // [REQ-005] Soft drop on a resting piece scores nothing but restarts the lock delay like a sideways move.
  function doInput(action) {
    if (status !== "running" || !current) return;
    if (action === "left") {
      shift(-1);
    } else if (action === "right") {
      shift(1);
    } else if (action === "rotateCW") {
      rotateCW();
    } else if (action === "softDrop") {
      if (fits(current, current.row + 1, current.col)) {
        current.row += 1;
        score += SOFT_DROP_POINTS;
      } else {
        resetLock();
      }
    } else if (action === "hardDrop") {
      while (fits(current, current.row + 1, current.col)) {
        current.row += 1;
        score += HARD_DROP_POINTS;
      }
      lockPiece();
    } else if (action === "hold") {
      holdPiece();
    }
  }

  // [REQ-007] Gravity interval in ms for the current level.
  function gravityInterval() {
    return Math.max(100, 1000 - (level - 1) * 100);
  }

  function stopTimer() {
    if (timer !== null) { clearInterval(timer); timer = null; }
  }

  function startTimer() {
    stopTimer();
    timer = setInterval(function () {
      gravityStep();
      render();
    }, gravityInterval());
  }

  // [REQ-001] Draw the whole game state into the DOM, synchronously.
  function render() {
    var drawn = board.map(function (row) { return row.slice(); });
    if (current) {
      cellsOf(current, current.row, current.col).forEach(function (rc) {
        drawn[rc[0]][rc[1]] = current.type;
      });
    }
    for (var r = 0; r < ROWS; r++) {
      for (var c = 0; c < COLS; c++) {
        var v = drawn[r][c] || "";
        var el = cellEls[r][c];
        if (el.getAttribute("data-piece") !== v) {
          el.setAttribute("data-piece", v);
          el.setAttribute("data-filled", v ? "true" : "false");
        }
      }
    }
    // [REQ-004] Upcoming pieces in their board colour. [REQ-006] Only the next one is shown.
    previewItems.forEach(function (item, i) {
      var type = upcoming[i] || "";
      item.el.setAttribute("data-piece", type);
      item.el.hidden = !type;
      item.minis.forEach(function (m) { m.setAttribute("data-piece", ""); });
      if (type) {
        SHAPES[type].forEach(function (o) {
          item.minis[o[0] * 4 + o[1]].setAttribute("data-piece", type);
        });
      }
    });
    // [REQ-007] Held piece in its board colour.
    holdEl.setAttribute("data-piece", hold || "");
    holdMinis.forEach(function (m) { m.setAttribute("data-piece", ""); });
    if (hold) {
      SHAPES[hold].forEach(function (o) {
        holdMinis[o[0] * 4 + o[1]].setAttribute("data-piece", hold);
      });
    }
    scoreEl.textContent = String(score);
    levelEl.textContent = String(level);
    linesEl.textContent = String(lines);
    statusEl.hidden = status !== "gameover";
  }

  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
  function newGame(queue) {
    board = emptyBoard();
    score = 0;
    level = 1;
    lines = 0;
    hold = null;
    holdUsed = false;
    status = "running";
    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
    current = null;
    spawn();
    if (status === "running") startTimer();
    render();
  }

  window.__tetris = {
    newGame: function (queue) { newGame(queue); },

    setQueue: function (queue) {
      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
      fillUpcoming();
      render();
    },

    setBoard: function (rows) {
      var b = emptyBoard();
      for (var r = 0; r < ROWS; r++) {
        var line = (rows && rows[r]) || "";
        for (var c = 0; c < COLS; c++) {
          var ch = line.charAt(c);
          b[r][c] = isType(ch) ? ch : null;
        }
      }
      board = b;
      render();
    },

    tick: function (n) {
      if (n === undefined) n = 1;
      for (var i = 0; i < n; i++) gravityStep();
      if (status === "running") startTimer();
      render();
    },

    // [REQ-007] Set the level for testing. Line levelling continues from here.
    setLevel: function (n) {
      n = Math.floor(Number(n));
      if (!(n >= 1)) return;
      level = n;
      if (status === "running") startTimer();
      render();
    },

    input: function (action) {
      doInput(action);
      render();
    },

    getBoard: function () {
      return board.map(function (row) {
        return row.map(function (v) { return v || "."; }).join("");
      });
    },

    getState: function () {
      return {
        current: current
          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
          : null,
        next: upcoming.slice(),
        score: score,
        level: level,
        lines: lines,
        status: status,
        dropInterval: gravityInterval(),
        hold: hold
      };
    }
  };

  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop", c: "hold", C: "hold", Shift: "hold" };

  document.addEventListener("keydown", function (e) {
    var action = KEYS[e.key];
    if (!action) return;
    e.preventDefault();
    window.__tetris.input(action);
  });

  document.getElementById("restart").addEventListener("click", function (e) {
    e.currentTarget.blur();
    newGame();
  });

  buildDom();
  newGame();
})();
</script>
